'use strict';
const GUEST_UI5={bind,storesView,liveView,help};
TITLES.guests='Hosté, návraty & recenze';
let guestFilter5='all';
const guestQualityLabel5=n=>n===null?'—':number(n,1);
function guestGroupRows5(s){const h=s.guests5.last;return h?`<div class="table-scroll"><table class="data"><thead><tr><th>Skupina</th><th>Návštěvy / obslouženo</th><th>Stálé návštěvy</th><th>Stálí hosté</th><th>Spokojenost</th><th>Hlavní důvod</th></tr></thead><tbody>${h.groups.map(g=>`<tr><td><strong>${GUEST_TYPES5[g.id].name}</strong><small>Čekání ${number(g.wait,1)} min · kávy ${guestQualityLabel5(g.quality)}/100</small></td><td>${g.arrivals} / ${g.served}<small>Fronta ${g.lostQueue} · místa ${g.lostSeats} · zásoby ${g.lostStock} · zavření ${g.lostClosing}</small></td><td>${g.returned}</td><td>${g.regulars}<small>+${g.gained} získáno · −${g.departed} odchází</small></td><td class="${g.satisfaction<50?'bad':g.satisfaction>=75?'good':''}">${number(g.satisfaction,1)} / 100</td><td>${esc(g.reason)}<small><button class="quiet mini" data-guest-group="${s.id}" data-guest-type="${g.id}">Rozebrat zkušenost</button></small></td></tr>`).join('')}</tbody></table></div>`:empty('První zkušenosti se zaznamenají po odehrání týdne. Stálí hosté se získávají postupně.');}
function guestTrend5(s){const a=s.guests5.history;if(a.length<2)return '<p class="sub">Trend se objeví po druhém zaznamenaném týdnu.</p>';const max=Math.max(1,...a.map(h=>h.regulars)),points=a.map((h,i)=>`${12+i/(a.length-1)*496},${96-h.regulars/max*75}`).join(' ');return `<svg class="guest-trend5" viewBox="0 0 520 120" role="img" aria-label="Vývoj aktivních stálých hostů: ${a.map(h=>'T'+h.week+' '+h.regulars).join(', ')}"><path d="M12 96H508" stroke="#ddd8c8"/><polyline points="${points}" fill="none" stroke="#264b3b" stroke-width="3"/><text x="12" y="115" font-size="13">T${a[0].week}</text><text x="458" y="115" font-size="13">T${a.at(-1).week}</text><text x="12" y="15" font-size="13">Stálí hosté · maximum ${max}</text></svg>`;}
function guestsView(){if(guestFilter5!=='all'&&!state.stores.some(s=>s.id===guestFilter5))guestFilter5='all';const list=state.stores.filter(s=>guestFilter5==='all'||s.id===guestFilter5),hist=list.map(s=>s.guests5.last).filter(Boolean),reviews=list.flatMap(s=>s.guests5.reviews),arrivals=hist.reduce((n,h)=>n+h.arrivals,0),served=hist.reduce((n,h)=>n+h.served,0),returned=hist.reduce((n,h)=>n+h.returned,0),regulars=list.reduce((n,s)=>n+s.guests5.cohorts.reduce((n,c)=>n+c.regulars,0),0),rating=reviews.length?reviews.reduce((n,r)=>n+r.stars,0)/reviews.length:null;return `<div class="view-toolbar"><p class="intro">Zjisti, kdo přichází, kdo se vrací a co hostům vadí. Návštěvy mohou zahrnovat opakované příchody; stálí hosté jsou aktivní zákaznický okruh jednotlivých poboček.</p>${field('Kavárna',`<select id="guestFilter5">${option('all','Všechny kavárny',guestFilter5)}${state.stores.map(s=>option(s.id,loc(s.id).city+' · '+loc(s.id).name,guestFilter5)).join('')}</select>`)}</div><div class="report-overview5">${metric('AKTIVNÍ STÁLÍ HOSTÉ',regulars,'Součet okruhů poboček; jeden člověk může patřit do více')}${metric('NÁVŠTĚVY STÁLÝCH HOSTŮ',hist.length?returned:'—',hist.length?'Z '+served+' obsloužených návštěv':'Odehraj první týden')}${metric('OBSLUHA NÁVŠTĚV',hist.length?number(served/Math.max(1,arrivals)*100,1)+' %':'—',arrivals+' příchozích v posledním týdnu')}${metric('VEŘEJNÉ HODNOCENÍ',rating===null?'—':number(rating,1)+' / 5',reviews.length+' posledních evidovaných recenzí')}</div><div class="actions"><button class="soft" data-goto="performance">Report firmy</button><button class="soft" data-goto="crew">Týmy & směny</button><button class="soft" data-goto="interior">Prostředí & vybavení</button><button class="soft" data-goto="menu">Ceny a nabídka</button></div>${list.map(s=>{const h=s.guests5.last;return `<section class="card" style="margin-top:24px"><div class="card-head"><div><h2>${esc(loc(s.id).name)}</h2><p class="sub">${esc(loc(s.id).city)} · ${h?'T'+h.week+' · '+esc(h.owner):'Zatím bez výsledků'}${s.franchise?' · franšíza':''}</p></div><div class="actions"><button class="soft mini" data-guest-live="${s.id}">Průběh obsluhy</button><button class="soft mini" data-guest-only="${s.id}">Jen tuto pobočku</button></div></div>${h?`<div class="guest-mix5" aria-label="Složení návštěv">${h.groups.map(g=>`<div><span>${GUEST_TYPES5[g.id].name}</span><div class="bar"><i style="width:${g.arrivals/Math.max(1,h.arrivals)*100}%"></i></div><strong>${number(g.arrivals/Math.max(1,h.arrivals)*100,1)} %</strong></div>`).join('')}</div>`:''}${guestGroupRows5(s)}${guestTrend5(s)}${h?`<p class="sub">Stálý okruh: ${h.before} před týdnem + ${h.gained} získaných − ${h.departed} odchozích = ${h.regulars}. Spokojenost příchozích ${number(h.satisfaction,1)}/100. Neobsloužená návštěva se do návratů nepočítá.</p>`:''}<h3>Veřejné recenze</h3><p class="sub">Výběr zkušeností z odehraného týdne, nejvýše tři recenze za týden. Hodnocení vychází z dané skupiny, včetně neobsloužených hostů; nejde o recenzi každé návštěvy. Uchovává se posledních 30 recenzí.</p><div class="cards">${s.guests5.reviews.slice(-9).reverse().map(r=>`<article class="card guest-review5"><div class="card-head"><strong>${GUEST_TYPES5[r.group].name}</strong><span aria-label="${r.stars} z pěti hvězd">${'★'.repeat(r.stars)}${'☆'.repeat(5-r.stars)}</span></div><p>${esc(r.text)}</p><p class="sub">T${r.week} · spokojenost ${number(r.satisfaction,1)}/100 · obslouženo ${r.served}/${r.arrivals} · čekání ${number(r.wait,1)} min · káva ${guestQualityLabel5(r.quality)}/100 · útrata za nápoj ${money(r.price)}</p>${r.reply?`<p class="good">${r.reply.choice==='reply'?'Odpovězeno':'Odpovězeno s kompenzací'} v T${r.reply.week} · ${money(r.reply.cost)}. Původní hodnocení zachováno.</p>`:`<div class="actions"><button class="soft mini" data-guest-reply="${s.id}" data-guest-review="${r.id}" data-guest-choice="reply" ${state.over?'disabled':''}>Odpovědět · 750 Kč</button><button class="quiet mini" data-guest-reply="${s.id}" data-guest-review="${r.id}" data-guest-choice="compensate" ${state.over?'disabled':''}>Odpověď + kompenzace · 2 250 Kč</button></div>`}</article>`).join('')||empty('Zatím žádná recenze; starší zkušenosti se nedoplňují.')}</div></section>`;}).join('')||empty('Otevři první kavárnu. Každá adresa získá vlastní zákaznický okruh.')}<section class="card" style="margin-top:24px"><h3>Co jednotlivé skupiny hledají</h3><div class="table-scroll"><table class="data"><thead><tr><th>Hosté</th><th>Největší vliv</th><th>Trpělivost ve frontě</th><th>Zájem o sezení</th></tr></thead><tbody>${GUEST_KEYS5.map(id=>{const g=GUEST_TYPES5[id],key=Object.keys(g.weights).sort((a,b)=>g.weights[b]-g.weights[a])[0];return `<tr><td>${g.name}</td><td>${({value:'Cena a hodnota',coffee:'Káva',wait:'Rychlost',place:'Prostředí'})[key]}</td><td>${g.patience*10} minut</td><td>${number(g.seated*100)} %</td></tr>`;}).join('')}</tbody></table></div><p class="sub">Jde o zjednodušený herní model v desetiminutových krocích. Lokalita určuje základní mix. Cena, zkušenosti stálých hostů a poslední veřejné hodnocení ovlivní další poptávku. Odpověď stojí čas týmu; kompenzace zahrnuje i péči o zákazníka. Vztahu dané skupiny pomohou v příštím týdnu nejvýše o 3 body a nenahradí opravu provozu. Historie sleduje okruhy hostů, nikoli jednotlivé pojmenované osoby.</p></section>`;}
function guestGroupDialog5(id,type){const s=state.stores.find(s=>s.id===id),g=s?.guests5.last?.groups.find(g=>g.id===type);if(!g)return;const cfg=GUEST_TYPES5[type];show(`<span class="eyelabel">${esc(loc(id).name)} · T${s.guests5.last.week}</span><h2>${cfg.name}</h2><p>${esc(g.reason)}</p>${rows([['Návštěvy / obslouženo',g.arrivals+' / '+g.served],['Návraty stálých hostů',g.returned],['Cena / očekávání skupiny',money(g.price)+' / '+money(g.expectedPrice)],['Kvalita skutečně odebrané kávy',guestQualityLabel5(g.quality)+' / 100'],['Čekání obsloužených hostů',number(g.wait,1)+' min'],['Fronta / nedostatek míst',g.lostQueue+' / '+g.lostSeats],['Zásoby / zavření',g.lostStock+' / '+g.lostClosing]])}<h3>Z čeho vznikla spokojenost</h3>${rows(Object.entries(g.scores).map(([k,n])=>[({value:'Cena a hodnota',coffee:'Káva',wait:'Rychlost',place:'Prostředí'})[k]+' · váha '+number(cfg.weights[k]*100)+' %',number(n,1)+' / 100']))}<p class="sub">Vážené zkušenosti snižují neobsloužené návštěvy. Péče o hosty může přidat nejvýše 3 body. Výsledná spokojenost ${number(g.satisfaction,1)}/100. ${g.gained} hostů se přidalo ke stálým, ${g.departed} jich odešlo. Kvalita je průměr skutečně odebrané kávy pobočky; skupiny nepijí vlastní oddělené šarže.</p>`);}
storesView=function(){return `<div class="actions"><button class="primary" data-goto="guests">Hosté, návraty & důvody recenzí</button></div>`+GUEST_UI5.storesView();};
liveView=function(){return `<div class="actions"><button class="soft" data-goto="guests">Zkušenosti skupin & recenze</button></div>`+GUEST_UI5.liveView();};
bind=function(){GUEST_UI5.bind();if(el('guestFilter5'))el('guestFilter5').onchange=()=>{guestFilter5=el('guestFilter5').value;render();};on('[data-guest-only]',b=>{guestFilter5=b.dataset.guestOnly;render();});on('[data-guest-group]',b=>guestGroupDialog5(b.dataset.guestGroup,b.dataset.guestType));on('[data-guest-live]',b=>{liveStore=b.dataset.guestLive;liveDay5=0;liveFrame=0;goto('live');});on('[data-guest-reply]',b=>{try{const id=b.dataset.guestReply,rid=b.dataset.guestReview,choice=b.dataset.guestChoice,q=guestReplyQuote5(id,rid,choice);confirmAction('Reagovat na recenzi?','Náklad '+money(q.fee)+'. Péče o tuto skupinu pomůže při příštím vyhodnocení nejvýše o '+(choice==='reply'?1:3)+' body; původní text a hvězdy zůstanou zachované. Opakovanou odpověď hra nepovolí.',()=>replyGuest5(id,rid,choice,q),choice==='reply'?'Odpovědět':'Odpovědět a kompenzovat');}catch(e){toast(e.message);}});};
help=function(){GUEST_UI5.help();const p=document.createElement('p');p.textContent='Hosté & recenze: každá kavárna má pět skupin s vlastní citlivostí na cenu, chuť, čekání a prostředí. Skupiny opravdu čekají ve frontě s různou trpělivostí. Káva a obsluha omezují skutečné prodeje; neobsloužení hosté se nepočítají mezi návraty. Stálý okruh roste získanými hosty a klesá odchody. Recenze jsou výběrem zkušeností z daného týdne. Odpověď stojí 750 Kč, s kompenzací 2 250 Kč; původní hvězdy nepřepíše a opravu provozu nenahradí. Report firmy obsahuje další kategorii Hosté & recenze. Starší uložené hry začnou bez vymyšlené historie hostů.';el('modalContent').append(p);};el('help').onclick=help;
render();
